	    async groupGlobalIostatTracks(tag, group) {
	        const iostatTracks = [];
	        const devMap = new Map();
	        for (const track of this.tracksToAdd) {
	            if (track.name.startsWith(tag)) {
	                iostatTracks.push(track);
	            }
	        }
	        if (iostatTracks.length === 0) {
	            return;
	        }
	        for (const track of iostatTracks) {
	            const name = track.name.split('.', 3);
	            if (!devMap.has(name[1])) {
	                devMap.set(name[1], (0, uuid_1.v4)());
	            }
	            track.name = name[2];
	            track.trackGroup = devMap.get(name[1]);
	        }
	        for (const [key, value] of devMap) {
	            const groupName = group + key;
	            const summaryTrackId = (0, uuid_1.v4)();
	            this.tracksToAdd.push({
	                id: summaryTrackId,
	                engineId: this.engineId,
	                kind: null_track_1.NULL_TRACK_KIND,
	                trackSortKey: state_1.PrimaryTrackSortKey.NULL_TRACK,
	                name: groupName,
	                trackGroup: undefined,
	                config: {},
	            });
	            const addGroup = actions_1.Actions.addTrackGroup({
	                engineId: this.engineId,
	                summaryTrackId,
	                name: groupName,
	                id: value,
	                collapsed: true,
	            });
	            this.addTrackGroupActions.push(addGroup);
	        }
	    }
	    async groupGlobalUfsCmdTagTracks(tag, group) {
	        const ufsCmdTagTracks = [];
	        for (const track of this.tracksToAdd) {
	            if (track.name.startsWith(tag)) {
	                ufsCmdTagTracks.push(track);
	            }
	        }
	        if (ufsCmdTagTracks.length === 0) {
	            return;
	        }
	        const id = (0, uuid_1.v4)();
	        const summaryTrackId = (0, uuid_1.v4)();
	        ufsCmdTagTracks[0].id = summaryTrackId;
	        for (const track of ufsCmdTagTracks) {
	            track.trackGroup = id;
	        }
	        const addGroup = actions_1.Actions.addTrackGroup({
	            engineId: this.engineId,
	            summaryTrackId,
	            name: group,
	            id,
	            collapsed: true,
	        });
	        this.addTrackGroupActions.push(addGroup);
	    }
	    async groupGlobalBuddyInfoTracks() {
	        const buddyInfoTracks = [];
	        const devMap = new Map();
	        for (const track of this.tracksToAdd) {
	            if (track.name.startsWith(BUDDY_INFO_TAG)) {
	                buddyInfoTracks.push(track);
	            }
	        }
	        if (buddyInfoTracks.length === 0) {
	            return;
	        }
	        for (const track of buddyInfoTracks) {
	            const tokens = track.name.split('[');
	            const node = tokens[1].slice(0, -1);
	            const zone = tokens[2].slice(0, -1);
	            const size = tokens[3].slice(0, -1);
	            const groupName = 'Buddyinfo:  Node: ' + node + ' Zone: ' + zone;
	            if (!devMap.has(groupName)) {
	                devMap.set(groupName, (0, uuid_1.v4)());
	            }
	            track.name = 'Size: ' + size;
	            track.trackGroup = devMap.get(groupName);
	        }
	        for (const [key, value] of devMap) {
	            const groupName = key;
	            const summaryTrackId = (0, uuid_1.v4)();
	            this.tracksToAdd.push({
	                id: summaryTrackId,
	                engineId: this.engineId,
	                kind: null_track_1.NULL_TRACK_KIND,
	                trackSortKey: state_1.PrimaryTrackSortKey.NULL_TRACK,
	                name: groupName,
	                trackGroup: undefined,
	                config: {},
	            });
	            const addGroup = actions_1.Actions.addTrackGroup({
	                engineId: this.engineId,
	                summaryTrackId,
	                name: groupName,
	                id: value,
	                collapsed: true,
	            });
	            this.addTrackGroupActions.push(addGroup);
	        }
	    }
	    async groupTracksByRegex(regex, groupName) {
	        let groupUuid = undefined;
	        for (const track of this.tracksToAdd) {
	            if (regex.test(track.name)) {
	                if (groupUuid === undefined) {
	                    groupUuid = (0, uuid_1.v4)();
	                }
	                track.trackGroup = groupUuid;
	            }
	        }
	        if (groupUuid !== undefined) {
	            const summaryTrackId = (0, uuid_1.v4)();
	            this.tracksToAdd.push({
	                id: summaryTrackId,
	                engineId: this.engineId,
	                kind: null_track_1.NULL_TRACK_KIND,
	                trackSortKey: state_1.PrimaryTrackSortKey.NULL_TRACK,
	                name: groupName,
	                trackGroup: undefined,
	                config: {},
	            });
	            const addGroup = actions_1.Actions.addTrackGroup({
	                engineId: this.engineId,
	                summaryTrackId,
	                name: groupName,
	                id: groupUuid,
	                collapsed: true,
	            });
	            this.addTrackGroupActions.push(addGroup);
	        }
	    }
	    applyDefaultCounterScale() {
	        for (const track of this.tracksToAdd) {
	            if (track.kind === counter_1.COUNTER_TRACK_KIND) {
	                const scaleConfig = {
	                    scale: getCounterScale(track.name),
	                };
	                track.config = Object.assign({}, track.config, scaleConfig);
	            }
	        }
	    }
