	    async addFtraceTrack(engine) {
	        const query = `select distinct cpu
          from ftrace_event
          where cpu + 1 > 1 or utid + 1 > 1`;
	        const result = await engine.query(query);
	        const it = result.iter({ cpu: query_result_1.NUM });
	        let groupUuid = undefined;
	        let summaryTrackId = undefined;
	        // use the first one as the summary track
	        for (let row = 0; it.valid(); it.next(), row++) {
	            if (groupUuid === undefined) {
	                groupUuid = 'ftrace-track-group';
	                summaryTrackId = (0, uuid_1.v4)();
	                this.tracksToAdd.push({
	                    engineId: this.engineId,
	                    kind: null_track_1.NULL_TRACK_KIND,
	                    trackSortKey: state_1.PrimaryTrackSortKey.NULL_TRACK,
	                    name: `Ftrace Events`,
	                    trackGroup: undefined,
	                    config: {},
	                    id: summaryTrackId,
	                });
	            }
	            this.tracksToAdd.push({
	                engineId: this.engineId,
	                kind: ftrace_1.FTRACE_RAW_TRACK_KIND,
	                trackSortKey: state_1.PrimaryTrackSortKey.ORDINARY_TRACK,
	                name: `Ftrace Events Cpu ${it.cpu}`,
	                trackGroup: groupUuid,
	                config: { cpu: it.cpu },
	            });
	        }
	        if (groupUuid !== undefined && summaryTrackId !== undefined) {
	            const addGroup = actions_1.Actions.addTrackGroup({
	                engineId: this.engineId,
	                name: 'Ftrace Events',
	                id: groupUuid,
	                collapsed: true,
	                summaryTrackId,
	            });
	            this.addTrackGroupActions.push(addGroup);
	        }
	    }
	    async addAnnotationTracks(engine) {
	        const sliceResult = await engine.query(`
      select id, name, upid, group_name
      from annotation_slice_track
      order by name
    `);
	        const sliceIt = sliceResult.iter({
	            id: query_result_1.NUM,
	            name: query_result_1.STR,
	            upid: query_result_1.NUM,
	            group_name: query_result_1.STR_NULL,
	        });
	        const groupNameToIds = new Map();
	        for (; sliceIt.valid(); sliceIt.next()) {
	            const id = sliceIt.id;
	            const name = sliceIt.name;
	            const upid = sliceIt.upid;
	            const groupName = sliceIt.group_name;
	            let summaryTrackId = undefined;
	            let trackGroupId = upid === 0 ? state_1.SCROLLING_TRACK_GROUP : this.upidToUuid.get(upid);
	            if (groupName) {
	                // If this is the first track encountered for a certain group,
	                // create an id for the group and use this track as the group's
	                // summary track.
	                const groupIds = groupNameToIds.get(groupName);
	                if (groupIds) {
	                    trackGroupId = groupIds.id;
	                }
	                else {
	                    trackGroupId = (0, uuid_1.v4)();
	                    summaryTrackId = (0, uuid_1.v4)();
	                    groupNameToIds.set(groupName, {
	                        id: trackGroupId,
	                        summaryTrackId,
	                    });
	                }
	            }
	            this.tracksToAdd.push({
	                id: summaryTrackId,
	                engineId: this.engineId,
	                kind: chrome_slices_1.SLICE_TRACK_KIND,
	                name,
	                trackSortKey: state_1.PrimaryTrackSortKey.ORDINARY_TRACK,
	                trackGroup: trackGroupId,
	                config: {
	                    maxDepth: 0,
	                    namespace: 'annotation',
	                    trackId: id,
	                },
	            });
	        }
	        for (const [groupName, groupIds] of groupNameToIds) {
	            const addGroup = actions_1.Actions.addTrackGroup({
	                engineId: this.engineId,
	                summaryTrackId: groupIds.summaryTrackId,
	                name: groupName,
	                id: groupIds.id,
	                collapsed: true,
	            });
	            this.addTrackGroupActions.push(addGroup);
	        }
	        const counterResult = await engine.query(`
    SELECT
      id,
      name,
      upid,
      min_value as minValue,
      max_value as maxValue
    FROM annotation_counter_track`);
	        const counterIt = counterResult.iter({
	            id: query_result_1.NUM,
	            name: query_result_1.STR,
	            upid: query_result_1.NUM,
	            minValue: query_result_1.NUM_NULL,
	            maxValue: query_result_1.NUM_NULL,
	        });
	        for (; counterIt.valid(); counterIt.next()) {
	            const id = counterIt.id;
	            const name = counterIt.name;
	            const upid = counterIt.upid;
	            const minimumValue = counterIt.minValue === null ? undefined : counterIt.minValue;
	            const maximumValue = counterIt.maxValue === null ? undefined : counterIt.maxValue;
	            this.tracksToAdd.push({
	                engineId: this.engineId,
	                kind: 'CounterTrack',
	                name,
	                trackSortKey: state_1.PrimaryTrackSortKey.COUNTER_TRACK,
	                trackGroup: upid === 0 ? state_1.SCROLLING_TRACK_GROUP :
	                    this.upidToUuid.get(upid),
	                config: {
	                    name,
	                    namespace: 'annotation',
	                    trackId: id,
	                    minimumValue,
	                    maximumValue,
	                },
	            });
	        }
	    }
	    async addThreadStateTracks(engine) {
	        const result = await engine.query(`
      select
        utid,
        tid,
        upid,
        pid,
        thread.name as threadName
      from
        thread_state
        left join thread using(utid)
        left join process using(upid)
      where utid != 0
      group by utid`);
	        const it = result.iter({
	            utid: query_result_1.NUM,
	            upid: query_result_1.NUM_NULL,
	            tid: query_result_1.NUM_NULL,
	            pid: query_result_1.NUM_NULL,
	            threadName: query_result_1.STR_NULL,
	        });
	        for (; it.valid(); it.next()) {
	            const utid = it.utid;
	            const tid = it.tid;
	            const upid = it.upid;
	            const threadName = it.threadName;
	            const uuid = this.getUuidUnchecked(utid, upid);
	            if (uuid === undefined) {
	                // If a thread has no scheduling activity (i.e. the sched table has zero
	                // rows for that uid) no track group will be created and we want to skip
	                // the track creation as well.
	                continue;
	            }
	            const kind = thread_state_1.THREAD_STATE_TRACK_KIND;
	            this.tracksToAdd.push({
	                engineId: this.engineId,
	                kind,
	                name: TrackDecider.getTrackName({ utid, tid, threadName, kind }),
	                trackGroup: uuid,
	                trackSortKey: {
	                    utid,
	                    priority: state_1.InThreadTrackSortKey.THREAD_SCHEDULING_STATE_TRACK,
	                },
	                config: { utid, tid },
	            });
	        }
	    }
